<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { RefreshCw } from 'lucide-vue-next'
import { getDemandAnalysis } from '../services/logisticsService'
import '../assets/demand-analysis.css'
const props = defineProps({ zones: { type: Array, default: () => [] } })
const zoneId = ref(''); const loading = ref(false); const error = ref(''); const analysis = ref(null)
const weekdays = ['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo']; const labels = { total_pedidos: 'Pedidos registrados', promedio_diario: 'Promedio diario', entregados: 'Pedidos entregados', cancelados: 'Pedidos cancelados', porcentaje_cancelaciones: '% de cancelaciones' }
const metrics = computed(() => analysis.value?.indicadores || {}); const heat = computed(() => analysis.value?.calor || []); const maxHeat = computed(() => Math.max(1, ...heat.value.map((item) => Number(item.total || 0)))); const insufficient = computed(() => analysis.value?.meta?.historial_insuficiente)
function hour(value) { return `${String(value).padStart(2,'0')}:00` }; function metric(key) { return key === 'porcentaje_cancelaciones' ? `${Number(metrics.value[key] || 0).toFixed(2)}%` : key === 'promedio_diario' ? Number(metrics.value[key] || 0).toFixed(2) : Number(metrics.value[key] || 0) }
function heatValue(day, hourValue) { return heat.value.find((item) => Number(item.dia) === day && Number(item.hora) === hourValue)?.total || 0 }; function intensity(day, hourValue) { return Math.max(.05, heatValue(day, hourValue) / maxHeat.value) }
async function load() { loading.value = true; error.value = ''; try { analysis.value = await getDemandAnalysis(zoneId.value) } catch (e) { error.value = e.message || 'No se pudo cargar el análisis. Aplica primero la migración de análisis histórico.' } finally { loading.value = false } }
watch(zoneId, load); onMounted(load)
</script>
<template><section class="demand-analysis"><div class="demand-analysis__toolbar"><select v-model="zoneId"><option value="">Todas las zonas</option><option v-for="zone in zones" :key="zone.id" :value="zone.id">{{ zone.nombre }}</option></select><button class="admin-icon-button" :disabled="loading" @click="load"><RefreshCw :size="18" /></button></div><p v-if="error" class="admin-alert">{{ error }}</p><div v-if="loading" class="admin-empty">Calculando demanda histórica…</div><template v-else-if="analysis"><p v-if="insufficient" class="demand-analysis__notice">El historial disponible es menor a 90 días. Se muestran únicamente los datos reales encontrados entre {{ analysis.meta.datos_desde ? new Date(analysis.meta.datos_desde).toLocaleDateString('es-SV') : '—' }} y {{ analysis.meta.datos_hasta ? new Date(analysis.meta.datos_hasta).toLocaleDateString('es-SV') : '—' }}.</p><div class="demand-kpis"><article v-for="key in ['total_pedidos','promedio_diario','entregados','cancelados','porcentaje_cancelaciones']" :key="key" class="demand-kpi"><span>{{ labels[key] }}</span><strong>{{ metric(key) }}</strong></article><article class="demand-kpi"><span>Zona con mayor demanda</span><strong>{{ analysis.zona_mayor_demanda?.nombre || '—' }}</strong><small>{{ analysis.zona_mayor_demanda?.total || 0 }} pedidos</small></article><article class="demand-kpi"><span>Día con mayor demanda</span><strong>{{ analysis.dia_mayor_demanda?.dia ? weekdays[analysis.dia_mayor_demanda.dia - 1] : '—' }}</strong></article><article class="demand-kpi"><span>Franja mayor demanda</span><strong>{{ analysis.franja_mayor_demanda?.hora != null ? `${hour(analysis.franja_mayor_demanda.hora)}–${hour(Number(analysis.franja_mayor_demanda.hora)+3)}` : '—' }}</strong></article></div><div class="demand-grid"><section class="admin-panel demand-card"><h3>Demanda por zona</h3><div v-if="!analysis.zonas?.length" class="admin-empty">No hay pedidos en el período.</div><div v-for="item in analysis.zonas" :key="item.id" class="demand-bar-row"><span>{{ item.nombre }}</span><div><i :style="{ width: `${Math.max(2, Number(item.total) / Math.max(1, ...analysis.zonas.map((z) => Number(z.total))) * 100)}%` }" /></div><b>{{ item.total }}</b></div></section><section class="admin-panel demand-card"><h3>Demanda por día</h3><div class="demand-day-bars"><div v-for="item in analysis.dias" :key="item.dia"><b :style="{ height: `${Math.max(3, Number(item.total) / Math.max(1, ...analysis.dias.map((d) => Number(d.total))) * 100)}%` }" /><span>{{ weekdays[item.dia - 1].slice(0,3) }}</span><small>{{ item.total }}</small></div></div></section><section class="admin-panel demand-card"><h3>Demanda por franja horaria</h3><div class="demand-bar-row" v-for="item in analysis.franjas" :key="item.hora"><span>{{ hour(item.hora) }}</span><div><i :style="{ width: `${Math.max(2, Number(item.total) / Math.max(1, ...analysis.franjas.map((f) => Number(f.total))) * 100)}%` }" /></div><b>{{ item.total }}</b></div></section><section class="admin-panel demand-card demand-card--wide"><h3>Mapa de calor · día y hora</h3><div class="heatmap"><div class="heatmap__corner" /><span v-for="day in weekdays" :key="day" class="heatmap__day">{{ day.slice(0,3) }}</span><template v-for="hourValue in [0,3,6,9,12,15,18,21]" :key="hourValue"><span class="heatmap__hour">{{ hour(hourValue) }}</span><span v-for="day in [1,2,3,4,5,6,7]" :key="`${hourValue}-${day}`" class="heatmap__cell" :title="`${weekdays[day-1]} ${hour(hourValue)}: ${heatValue(day,hourValue)} pedidos`" :style="{ opacity: intensity(day,hourValue) }">{{ heatValue(day,hourValue) }}</span></template></div></section><section class="admin-panel demand-card demand-card--wide"><h3>Cancelaciones por zona</h3><div v-if="!analysis.cancelaciones_zona?.length" class="admin-empty">No hay pedidos en el período.</div><table v-else class="admin-table"><thead><tr><th>Zona</th><th>Pedidos</th><th>Cancelados</th><th>%</th><th>Sin repartidores</th></tr></thead><tbody><tr v-for="item in analysis.cancelaciones_zona" :key="item.id"><td>{{ item.nombre }}</td><td>{{ item.total }}</td><td>{{ item.cancelados }}</td><td>{{ item.total ? ((item.cancelados / item.total) * 100).toFixed(2) : '0.00' }}%</td><td>{{ item.sin_repartidores }}</td></tr></tbody></table></section></div><small class="demand-analysis__updated">Análisis calculado en tiempo real · Última consulta: {{ analysis.meta.ultima_actualizacion ? new Date(analysis.meta.ultima_actualizacion).toLocaleString('es-SV') : '—' }}</small></template></section></template>
